#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PgStatusState {
    PG_STATE_IDLE = 0,
    PG_STATE_WORKING = 1,
    PG_STATE_BLOCKED = 2,
    PG_STATE_DONE = 3,
    PG_STATE_ERROR = 4,
}

#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
